<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import {
  createAnniversary,
  createTimeCapsule,
  deleteAnniversary,
  deleteTimeCapsule,
  getMemorial,
  getRitualSpace,
  openTimeCapsule,
  type Anniversary,
  type AnniversaryPayload,
  type Memorial,
  type RitualSpace,
  type TimeCapsule,
} from '@/api/memorials'

const route = useRoute()
const memorialId = computed(() => String(route.params.id))
const memorial = ref<Memorial | null>(null)
const space = ref<RitualSpace>({ archiveEntries: [], anniversaries: [], capsules: [], rituals: [] })
const loading = ref(true)
const busy = ref('')
const error = ref('')
const notice = ref('')
const editingId = ref<string | null>(null)
const anniversaryForm = reactive<AnniversaryPayload>({ anniversaryType: 'CUSTOM', title: '', eventDate: '', repeatRule: 'ANNUAL', reminderEnabled: false })
const capsuleForm = reactive<Pick<TimeCapsule, 'title' | 'body' | 'mediaId' | 'unlockOn' | 'visibility'>>({ title: '', body: '', mediaId: null, unlockOn: '', visibility: 'PRIVATE' })

const typeLabels: Record<Anniversary['anniversaryType'], string> = { BIRTHDAY: '生日', MEETING: '相遇日', ADOPTION: '领养日', FAREWELL: '离开周年', SEASON: '四季回忆', CUSTOM: '自定义日期' }
const upcoming = computed(() => space.value.anniversaries.map((item) => ({ item, next: nextOccurrence(item) })).sort((a, b) => a.next.localeCompare(b.next)))

function nextOccurrence(item: Anniversary) {
  if (item.repeatRule !== 'ANNUAL') return item.eventDate
  const today = new Date(); const original = new Date(`${item.eventDate}T12:00:00`)
  const candidate = new Date(today.getFullYear(), original.getMonth(), original.getDate(), 12)
  if (candidate < new Date(today.getFullYear(), today.getMonth(), today.getDate())) candidate.setFullYear(candidate.getFullYear() + 1)
  return candidate.toISOString().slice(0, 10)
}
function resetAnniversary() { editingId.value = null; Object.assign(anniversaryForm, { anniversaryType: 'CUSTOM', title: '', eventDate: '', repeatRule: 'ANNUAL', reminderEnabled: false }) }
function edit(item: Anniversary) { editingId.value = item.id; Object.assign(anniversaryForm, { anniversaryType: item.anniversaryType, title: item.title, eventDate: item.eventDate, repeatRule: item.repeatRule, reminderEnabled: item.reminderEnabled }); document.querySelector('#anniversary-form')?.scrollIntoView({ behavior: 'smooth' }) }
async function load() { loading.value = true; error.value = ''; try { const [current, currentSpace] = await Promise.all([getMemorial(memorialId.value), getRitualSpace(memorialId.value)]); memorial.value = current; space.value = currentSpace } catch (caught) { error.value = caught instanceof Error ? caught.message : '暂时无法打开纪念日历。' } finally { loading.value = false } }
async function saveAnniversary() { busy.value = 'anniversary'; error.value = ''; notice.value = ''; try { if (editingId.value) { const { updateAnniversary } = await import('@/api/memorials'); const updated = await updateAnniversary(memorialId.value, editingId.value, { ...anniversaryForm }); space.value.anniversaries = space.value.anniversaries.map((item) => item.id === updated.id ? updated : item); notice.value = '纪念日已经更新。' } else { const created = await createAnniversary(memorialId.value, { ...anniversaryForm }); space.value.anniversaries.push(created); notice.value = anniversaryForm.reminderEnabled ? '纪念日已收好，提醒会按你的选择保留。' : '纪念日已收好，提醒仍保持关闭。' } resetAnniversary() } catch (caught) { error.value = caught instanceof Error ? caught.message : '纪念日没有保存。' } finally { busy.value = '' } }
async function removeAnniversary(item: Anniversary) { if (!window.confirm(`移除“${item.title}”吗？`)) return; busy.value = item.id; try { await deleteAnniversary(memorialId.value, item.id); space.value.anniversaries = space.value.anniversaries.filter((entry) => entry.id !== item.id); if (editingId.value === item.id) resetAnniversary(); notice.value = '纪念日已移除。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '移除没有完成。' } finally { busy.value = '' } }
async function saveCapsule() { busy.value = 'capsule'; error.value = ''; notice.value = ''; try { const created = await createTimeCapsule(memorialId.value, { ...capsuleForm, title: capsuleForm.title.trim(), body: capsuleForm.body.trim(), mediaId: null }); space.value.capsules.push(created); Object.assign(capsuleForm, { title: '', body: '', mediaId: null, unlockOn: '', visibility: 'PRIVATE' }); notice.value = '这封信已经交给未来的你。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '时间胶囊没有保存。' } finally { busy.value = '' } }
async function openCapsule(item: TimeCapsule) { busy.value = item.id; error.value = ''; try { const opened = await openTimeCapsule(memorialId.value, item.id); space.value.capsules = space.value.capsules.map((entry) => entry.id === opened.id ? opened : entry); notice.value = `“${opened.title}”已经开启。` } catch (caught) { error.value = caught instanceof Error ? caught.message : '现在还不能打开这封时间胶囊。' } finally { busy.value = '' } }
async function removeCapsule(item: TimeCapsule) { if (!window.confirm(`移除时间胶囊“${item.title}”吗？`)) return; busy.value = item.id; try { await deleteTimeCapsule(memorialId.value, item.id); space.value.capsules = space.value.capsules.filter((entry) => entry.id !== item.id); notice.value = '时间胶囊已移除。' } catch (caught) { error.value = caught instanceof Error ? caught.message : '移除没有完成。' } finally { busy.value = '' } }
onMounted(load)
</script>

<template>
  <main class="calendar-page section-narrow">
    <div v-if="loading" class="account-empty">正在打开纪念日历…</div>
    <template v-else-if="memorial">
      <header class="calendar-intro"><div><p class="eyebrow">{{ memorial.petName }} 的时间信箱</p><h1>有些日子，<br />值得被轻轻记住。</h1><p>提醒默认关闭，时间胶囊也不会提前开启。节奏始终由你决定。</p></div><RouterLink class="button button-quiet" :to="`/editor/${memorialId}/ritual`">回到仪式中心</RouterLink></header>
      <p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-success" role="status">{{ notice }}</p>
      <section class="calendar-overview"><div><p class="eyebrow">下一次轻轻想起</p><h2>{{ upcoming[0] ? upcoming[0].item.title : '还没有设置纪念日' }}</h2><p>{{ upcoming[0] ? `${upcoming[0].next} · ${typeLabels[upcoming[0].item.anniversaryType]}` : '可以从相遇日、领养日或一个普通的季节开始。' }}</p></div><span aria-hidden="true">◒</span></section>
      <section class="calendar-section"><div class="section-head"><div><p class="eyebrow">纪念日历</p><h2>让日期成为邀请，不成为催促。</h2></div><p>开启提醒后，未来可接入站内通知；目前不会向你发送自动消息。</p></div><form id="anniversary-form" class="calendar-form" @submit.prevent="saveAnniversary"><label>日期类型<select v-model="anniversaryForm.anniversaryType"><option v-for="(label, key) in typeLabels" :key="key" :value="key">{{ label }}</option></select></label><label>给这一天的称呼<input v-model="anniversaryForm.title" required maxlength="60" placeholder="例如：第一次在窗边晒太阳" /></label><label>发生日期<input v-model="anniversaryForm.eventDate" required type="date" :max="new Date().toISOString().slice(0, 10)" /></label><label>重复方式<select v-model="anniversaryForm.repeatRule"><option value="ANNUAL">每年想起</option><option value="ONCE">只记录这一次</option><option value="OFF">不做提醒</option></select></label><label class="reminder-check"><input v-model="anniversaryForm.reminderEnabled" type="checkbox" />我愿意在临近这一天时收到克制提醒</label><div class="calendar-actions"><button class="button" :disabled="busy === 'anniversary'">{{ busy === 'anniversary' ? '正在保存…' : editingId ? '更新纪念日' : '收好这个日期' }}</button><button v-if="editingId" class="button button-quiet" type="button" @click="resetAnniversary">取消编辑</button></div></form><ol v-if="upcoming.length" class="anniversary-list"><li v-for="entry in upcoming" :key="entry.item.id"><time>{{ entry.next }}</time><div><strong>{{ entry.item.title }}</strong><p>{{ typeLabels[entry.item.anniversaryType] }} · {{ entry.item.repeatRule === 'ANNUAL' ? '每年想起' : entry.item.repeatRule === 'ONCE' ? '一次记录' : '不提醒' }}<span v-if="entry.item.reminderEnabled"> · 提醒已开启</span></p></div><div><button class="text-button" type="button" @click="edit(entry.item)">编辑</button><button class="text-button danger" type="button" :disabled="busy === entry.item.id" @click="removeAnniversary(entry.item)">删除</button></div></li></ol></section>
      <section class="capsule-section"><div class="capsule-copy"><p class="eyebrow">时间胶囊</p><h2>有些话，可以晚一点再打开。</h2><p>免费纪念空间可保存一封胶囊；高级会员可以收好更多。无论哪一种，都默认只有你自己能看见。</p></div><form class="capsule-form" @submit.prevent="saveCapsule"><label>写给未来的标题<input v-model="capsuleForm.title" required maxlength="80" placeholder="例如：明年春天再读" /></label><label>开启日期<input v-model="capsuleForm.unlockOn" required type="date" :min="new Date(Date.now() + 86400000).toISOString().slice(0, 10)" /></label><label>可见范围<select v-model="capsuleForm.visibility"><option value="PRIVATE">仅自己可见</option><option value="FAMILY">受邀亲友可见</option></select></label><label class="wide">想留给未来的话<textarea v-model="capsuleForm.body" required rows="5" maxlength="2000" placeholder="这一年里，我又想起了你什么？"></textarea></label><button class="button" :disabled="busy === 'capsule'">{{ busy === 'capsule' ? '正在封存…' : '封存这封信' }}</button></form><div v-if="space.capsules.length" class="capsule-list"><article v-for="capsule in space.capsules" :key="capsule.id" :class="{ unlocked: capsule.unlocked }"><div><span aria-hidden="true">{{ capsule.unlocked ? '✦' : '◒' }}</span><time>开启于 {{ capsule.unlockOn }}</time></div><h3>{{ capsule.title }}</h3><p v-if="capsule.unlocked">{{ capsule.body }}</p><p v-else>这封信会在约定的日子安静打开。</p><div><button v-if="capsule.unlocked" class="text-button" type="button" :disabled="busy === capsule.id" @click="openCapsule(capsule)">再次打开</button><button v-else class="text-button" type="button" disabled>尚未到开启日</button><button class="text-button danger" type="button" :disabled="busy === capsule.id" @click="removeCapsule(capsule)">删除</button></div></article></div></section>
    </template>
  </main>
</template>

<style scoped>
.calendar-page{padding-block:clamp(2rem,5vw,5rem)}.calendar-intro{display:flex;justify-content:space-between;align-items:end;gap:2rem;margin-bottom:2rem}.calendar-intro h1{margin:.45rem 0 1rem;font:clamp(42px,6vw,76px)/1.05 var(--font-serif)}.calendar-intro p:last-child{max-width:540px;color:var(--muted);line-height:1.85}.calendar-overview{display:flex;justify-content:space-between;align-items:center;min-height:220px;padding:clamp(28px,5vw,58px);margin-bottom:3rem;border:1px solid color-mix(in srgb,var(--primary) 34%,var(--border));border-radius:26px;background:radial-gradient(circle at 86% 16%,rgb(225 191 126 / 18%),transparent 27%),var(--surface)}.calendar-overview h2{margin:.45rem 0;font:clamp(30px,4.5vw,54px)/1.18 var(--font-serif)}.calendar-overview p{color:var(--muted)}.calendar-overview>span{font-size:4rem;color:var(--primary);opacity:.8}.calendar-section{padding-top:2rem;border-top:1px solid var(--border)}.section-head{display:grid;grid-template-columns:minmax(260px,.9fr) minmax(0,1.1fr);gap:2rem;align-items:end}.section-head h2,.capsule-copy h2{margin:.4rem 0;font:clamp(30px,4vw,50px)/1.18 var(--font-serif)}.section-head>p,.capsule-copy>p:last-child{max-width:440px;margin:0;color:var(--muted);line-height:1.75}.calendar-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;margin:2rem 0}.calendar-form label,.capsule-form label{display:grid;gap:.45rem;color:var(--muted);font-size:.88rem}.calendar-form input,.calendar-form select,.capsule-form input,.capsule-form select,.capsule-form textarea{width:100%;color:var(--text)}.reminder-check{grid-column:1/-1;display:flex!important;align-items:center;gap:.55rem;padding:.9rem;border:1px solid var(--border);color:var(--text)!important}.calendar-actions{grid-column:1/-1;display:flex;gap:.8rem}.anniversary-list{display:grid;gap:1px;margin:0;padding:0;border:1px solid var(--border);background:var(--border);list-style:none}.anniversary-list li{display:grid;grid-template-columns:130px 1fr auto;align-items:center;gap:1rem;padding:1rem 1.2rem;background:var(--canvas)}.anniversary-list time{color:var(--primary);font:1.1rem var(--font-serif)}.anniversary-list p{margin:.3rem 0 0;color:var(--muted);font-size:.86rem}.anniversary-list li>div:last-child{display:flex;gap:.8rem}.capsule-section{display:grid;grid-template-columns:minmax(240px,.8fr) minmax(0,1.2fr);gap:clamp(30px,7vw,100px);margin-top:clamp(4rem,8vw,8rem);padding-top:3rem;border-top:1px solid var(--border)}.capsule-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.capsule-form .wide,.capsule-form>.button{grid-column:1/-1}.capsule-form>.button{justify-self:start}.capsule-list{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1.5rem}.capsule-list article{position:relative;min-height:244px;padding:1.35rem;border:1px solid var(--border);border-radius:15px;background:color-mix(in srgb,var(--surface) 75%,transparent)}.capsule-list article.unlocked{border-color:color-mix(in srgb,var(--primary) 55%,var(--border));background:linear-gradient(145deg,color-mix(in srgb,var(--primary) 11%,var(--surface)),var(--surface))}.capsule-list article>div:first-child{display:flex;justify-content:space-between;gap:1rem;color:var(--muted);font-size:.78rem}.capsule-list article>div:first-child span{color:var(--primary);font-size:1.25rem}.capsule-list h3{margin:1.25rem 0 .65rem;font:1.3rem var(--font-serif)}.capsule-list p{color:var(--muted);line-height:1.7;white-space:pre-wrap}.capsule-list article>div:last-child{position:absolute;bottom:1rem;display:flex;gap:1rem}.danger{color:#c98585}@media(max-width:760px){.calendar-intro,.section-head,.capsule-section{display:grid}.calendar-form,.capsule-form,.capsule-list{grid-template-columns:1fr}.anniversary-list li{grid-template-columns:1fr}.capsule-list{margin-top:0}}@media(max-width:460px){.calendar-overview{align-items:start}.calendar-overview>span{font-size:2.5rem}.calendar-actions{flex-wrap:wrap}} 
</style>
